# -*- coding: utf-8 -*-
"""Science Stage 8 · Unit 13 Weather and Climate – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 8 (8ESc.01–8ESc.03, 8SIC.05, 8TWSc.02)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 13.1 Climate and weather · 8ESc.03, 8TWSc.02
# =====================================================================================================
READ["13.1"] = L(
    H("A cold day in a hot country",
      "One January day it snowed in a desert city that is usually hot and dry. A newspaper headline said: 'The climate has changed!'",
      "Was the headline right? What is the difference between weather and climate?"),
    I("What is weather?",
      "**Weather** is the state of the atmosphere in a place at a particular time: temperature, wind, cloud, humidity and **precipitation** (rain, snow, sleet, hail). It changes from day to day.",
      table=[["Instrument", "Measures"], ["thermometer", "temperature"], ["rain gauge", "rainfall"], ["hygrometer", "humidity"], ["wind vane", "wind direction"],
             ["anemometer", "wind speed"], ["barometer", "air pressure"]],
      then=["**Meteorologists** forecast the weather using data from weather stations, satellites, weather balloons and ocean buoys, fed into computer models."]),
    I("Climate and climate zones",
      "**Climate** is the usual pattern of weather in a region over a long time – worked out from averages of about **30 years** of readings. One unusual day is weather, not climate.",
      table=[["Climate zone", "Typical climate"], ["equatorial", "hot all year, very wet"], ["tropical", "hot; wet and dry seasons"], ["sub-tropical", "hot summers, mild winters; often dry"],
             ["temperate", "four seasons; rain all year; cool winters"], ["polar", "very cold all year; ice and snow"]],
      then=["The zones form bands around the Earth, depending on the distance from the equator."]),
    I("Data: a climate graph",
      "Average monthly temperature for a temperate city, from 30 years of readings:",
      fig={"kind": "linegraph", "x": {"min": 1, "max": 12, "step": 1, "label": "month (1 = January)"}, "y": {"min": 0, "max": 25, "step": 5, "label": "average temperature (°C)"},
           "series": [{"pts": [[1, 3], [2, 4], [3, 7], [4, 10], [5, 14], [6, 17], [7, 20], [8, 19], [9, 16], [10, 12], [11, 7], [12, 4]]}]},
      then=["The temperature rises through spring, peaks in summer and falls through autumn: four clear seasons."]),
    Y("Weather or climate?",
      grid("s8u13r11", "Is each statement about weather or climate?", ["Weather", "Climate"],
           [("It is raining heavily this afternoon.", "Weather"), ("This region has hot, dry summers and mild, wet winters.", "Climate"), ("Tomorrow will be windy.", "Weather"),
            ("Average January rainfall here is 80 mm.", "Climate")],
           "Today, or the long-term average?", "Short-term conditions are weather; long-term averages are climate.")),
    I("Predict, watch, explain: torch beams and latitude",
      "Two identical torches shine on squared paper: one straight down, one tilted. The straight torch makes a small, bright patch; the tilted one spreads the same light over a large, dimmer patch.",
      fig={"kind": "sciSunAngle"},
      then=["Near the equator the Sun's rays arrive almost straight down, concentrating the energy – it is hot. Near the poles the rays arrive at a low angle, spreading the energy over a larger area – it is cold."]),
    I("What affects climate?",
      "Four main factors:",
      table=[["Factor", "Effect"], ["**latitude** (distance from the equator)", "nearer the equator → hotter"], ["**altitude** (height above sea level)", "higher → colder (about 6 °C cooler per 1000 m)"],
             ["**relief** (shape of the land)", "mountains force air up: rainy on one side, dry 'rain shadow' on the other"], ["nearness to the **sea**", "coasts have milder winters and cooler summers than inland areas"]]),
    K("Key points",
      "**Weather**: day-to-day state of the atmosphere. **Climate**: average weather over about 30 years.",
      "Weather is measured with thermometers, rain gauges, hygrometers, wind vanes, anemometers, barometers.",
      "Climate zones: equatorial, tropical, sub-tropical, temperate, polar.",
      "Climate depends on latitude, altitude, relief and distance from the sea."),
    book=BK(
        [("weather", "the state of the atmosphere at a particular time and place"), ("climate", "the average weather of a region over a long time"),
         ("precipitation", "rain, snow, sleet or hail"), ("latitude", "distance north or south of the equator"), ("altitude", "height above sea level"),
         ("meteorologist", "a scientist who studies and forecasts weather")],
        [], [],
        [Ex("Explain the difference between weather and climate.", ans="Weather is the short-term condition of the atmosphere; climate is the long-term average pattern."),
         Ex("Name the instrument that measures: (a) wind speed (b) humidity (c) rainfall.", ans="(a) anemometer (b) hygrometer (c) rain gauge"),
         Ex("Use the climate graph: which months are warmest, and what is the range of average temperatures?", ans="July (and August); 20 − 3 = 17 °C"),
         Ex("Why is it colder at the top of a mountain on the equator than at sea level nearby?", ans="Temperature falls with altitude."),
         Ex("Back to 'Start here': was the headline right? Explain.", ans="No – one snowy day is weather; climate is the average over decades.", think=True)],
        ["tell weather from climate", "describe how weather is measured and forecast", "describe climate zones", "explain the factors that affect climate"],
        look=["the climate graph", "why latitude matters"],
        note="Read it after the video: weather, climate, climate zones and what affects climate (answers at the back)."),
)

# =====================================================================================================
# 13.2 Earth's climate cycles and climate change · 8ESc.01, 8ESc.02, 8SIC.05
# =====================================================================================================
READ["13.2"] = L(
    H("Ice where you live",
      "About 20 000 years ago, thick ice sheets covered much of northern Europe and North America, and the sea level was about 120 m lower than today.",
      "How do scientists know? And is the climate changing again now?"),
    I("Ice ages and warm periods",
      "Over hundreds of thousands of years Earth's climate has swung between cold **glacial periods** (ice ages) and warmer **interglacial periods**.",
      table=[["Glacial period", "Interglacial period"], ["ice sheets and glaciers spread", "ice melts"], ["sea level falls", "sea level rises"], ["climate drier", "climate warmer and wetter"]],
      then=["Natural causes include small changes in Earth's orbit and tilt, volcanic eruptions and changes in the Sun."]),
    I("Evidence for past climates",
      "Scientists read the climate of the past from many clues.",
      fig=CARD("Clues to past climates", [{"t": "Ice cores", "d": "bubbles of ancient air trapped in ice"}, {"t": "Glacial erratics and moraines", "d": "rocks dropped by old glaciers"},
                                           {"t": "Ocean sediments", "d": "microfossils of tiny sea creatures"}, {"t": "Tree rings and fossils", "d": "growth and species tell of past conditions"}], 4)),
    I("Real data: carbon dioxide at Mauna Loa",
      "Carbon dioxide in the air measured on a Hawaiian volcano, far from cities (ppm):",
      fig={"kind": "linegraph", "x": {"min": 1960, "max": 2020, "step": 10, "label": "year"}, "y": {"min": 300, "max": 420, "step": 20, "label": "carbon dioxide (ppm)"},
           "series": [{"pts": [[1960, 317], [1970, 326], [1980, 339], [1990, 354], [2000, 370], [2010, 390], [2020, 414]]}]},
      then=["From 1960 to 2020 the level rose by about 97 ppm, and it is rising faster now. The main cause is burning fossil fuels."]),
    Y("Read the graph",
      num("s8u13r21", "By how many ppm did carbon dioxide rise from 1990 to 2020?", 60, "Read both values and subtract.", "414 − 354 = 60 ppm.")),
    I("Predict, watch, explain: a model greenhouse",
      "Two jars stand under the same lamp, each with a thermometer; one is open, one has a clear lid.",
      table=[["Time", "Open jar", "Jar with lid"], ["0 min", "20 °C", "20 °C"], ["10 min", "23 °C", "27 °C"], ["20 min", "25 °C", "32 °C"]],
      then=["Light passes through the lid and warms the inside; the lid stops the warm air escaping, so heat builds up. Greenhouse gases in the atmosphere act in a similar way."]),
    I("The greenhouse effect",
      "**Greenhouse gases** such as **carbon dioxide**, **methane** and water vapour let sunlight through but trap some of the heat that Earth gives off.",
      fig={"kind": "sciGreenhouse"},
      then=["This natural greenhouse effect keeps Earth warm enough for life. Earth's early atmosphere was mostly carbon dioxide from volcanoes; it fell as oceans dissolved it and photosynthesis turned it into oxygen.",
            "Since the industrial revolution, burning fossil fuels and cutting down forests have added carbon dioxide; farm animals and rice fields add methane. More greenhouse gases trap more heat: **global warming**, which drives **climate change** – melting ice, rising seas, floods, droughts and heatwaves."]),
    Y("Greenhouse gases",
      mcq("s8u13r22", "Which human activity adds most to the extra carbon dioxide in the air?",
          [("burning fossil fuels", True, "Yes – coal, oil and gas release carbon dioxide."), ("planting trees", False, "Trees remove carbon dioxide."),
           ("using solar panels", False, "They release very little."), ("recycling paper", False, "This reduces emissions.")],
          "Which activity burns carbon-rich fuels?", "Burning fossil fuels is the largest source.")),
    K("Key points",
      "Earth's climate has cycled between **glacial** and **interglacial** periods; evidence from ice cores, erratics, moraines, sediments, tree rings and fossils.",
      "Carbon dioxide has risen sharply since measurements began, mainly from burning fossil fuels.",
      "The **greenhouse effect**: gases trap heat; more greenhouse gases → global warming → climate change.",
      "Reducing emissions and protecting forests help limit climate change."),
    book=BK(
        [("glacial period", "a long cold period when ice sheets spread (ice age)"), ("interglacial period", "a warmer period between glacials"),
         ("greenhouse effect", "greenhouse gases trapping heat in the atmosphere"), ("global warming", "the rise in Earth's average temperature"),
         ("climate change", "long-term changes in weather patterns")],
        [], [],
        [Ex("Describe what happens to ice and sea level in glacial and interglacial periods.", ans="Glacial: ice spreads, sea level falls. Interglacial: ice melts, sea level rises."),
         Ex("Give three kinds of evidence for past climates.", ans="e.g. ice cores, moraines / erratics, ocean sediment microfossils, tree rings, fossils"),
         Ex("Explain how the greenhouse effect keeps Earth warm.", ans="Sunlight passes through the atmosphere and warms Earth; greenhouse gases trap some of the heat Earth gives off."),
         Ex("Quick quiz.", ("Weather or climate: 'Today is windy'?", "weather"), ("What does an anemometer measure?", "wind speed"),
            ("Name two greenhouse gases.", "carbon dioxide and methane"), ("Why is it hotter at the equator?", "the Sun's rays arrive more directly, concentrating the energy")),
         Ex("Suggest two actions your school could take to reduce greenhouse gas emissions.", ans="e.g. solar panels, switching off lights, walking or cycling to school, planting trees, less food waste.", think=True)],
        ["describe ice ages and warm periods and their evidence", "explain the greenhouse effect", "explain how human activity is changing the climate"],
        look=["the Mauna Loa graph", "the greenhouse effect diagram"],
        note="Read it after the video: climate cycles, the greenhouse effect and climate change, plus a quick quiz (answers at the back)."),
)
